WITH c_cols AS (
    SELECT c.`cardKingdomFoilId`, c.`cardKingdomId`, c.`id`
    FROM cards AS c
)
SELECT * FROM c_cols;

WITH c_rows AS (
    SELECT `cardKingdomFoilId`, `cardKingdomId`, `id`
    FROM c_cols
    WHERE `cardKingdomFoilId` IS NOT NULL AND `cardKingdomId` IS NOT NULL
)
SELECT * FROM c_rows;

WITH t_join AS (
    SELECT c.`id`, c.`cardKingdomFoilId`, c.`cardKingdomId`
    FROM c_rows c
    JOIN cards cc ON c.id = cc.id
)
SELECT * FROM t_join;

WITH t_ids AS (
    SELECT `id`, `cardKingdomFoilId`, `cardKingdomId`
    FROM t_join
)
SELECT * FROM t_ids;

WITH final_ids AS (
    SELECT `id`
    FROM t_final
)
SELECT * FROM final_ids;

WITH final_output AS (
    SELECT `id`
    FROM final_ids
)
SELECT * FROM final_output;

